from save import save
def R(*a): return [{"da":d,"en":e} for d,e in a]
N={}
N["en bachelor"]={"explanation":'"En bachelor" means "a bachelor\'s degree". To say you are studying for one, use "at læse" (to study): "Hun læser en bachelor i historie" (She is studying for a bachelor\'s degree in history). To say an unmarried man, use "en ungkarl" (an unmarried man): "Min onkel er ungkarl" (My uncle is an unmarried man).',"related":R(("en kandidat","a master's degree"),("en ph.d.","a doctorate"),("en eksamen","an exam"),("et speciale","a thesis"))}
N["en backup"]={"explanation":'"En backup" means "a backup". To say you get your files back, use "at gendanne" (to restore) with "fra" (from): "Jeg gendanner mine filer fra en backup" (I restore my files from a backup).',"related":R(("en kopi","a copy"),("at gemme","to save"),("en sikkerhedskopi","a backup copy"))}
N["en badedragt"]={"explanation":'"En badedragt" means "a swimsuit". It is built from "at bade" (to bathe) and "en dragt" (a suit). To say you put it on, use "at tage på" (to put on): "Jeg tager badedragten på" (I put on my swimsuit).',"related":R(("en bikini","a bikini"),("badebukser","swim trunks"),("en badehætte","a swim cap"))}
N["en bademåtte"]={"explanation":'"En bademåtte" means "a bath mat". It is built from "at bade" (to bathe) and "en måtte" (a mat). The part "måtte" (mat) is also in "en gulvmåtte" (a floor mat).',"related":R(("et tæppe","a rug"),("en dørmåtte","a doormat"),("en musemåtte","a mouse mat"),("et håndklæde","a towel"))}
N["en badestrand"]={"explanation":'"En badestrand" means "a bathing beach". It is built from "at bade" (to bathe) and "en strand" (a beach). To say you swim in the sea, use "at bade" (to swim): "Vi bader i havet hele sommeren" (We swim in the sea all summer).',"related":R(("en livredder","a lifeguard"),("en sandstrand","a sandy beach"),("en kyst","a coast"))}
N["en badevægt"]={"explanation":'"En badevægt" means "a bathroom scale". It is built from "at bade" (to bathe) and "en vægt" (a weight). To say you step on it, use "at stå på" (to stand on): "Jeg står på badevægten hver morgen" (I step on the bathroom scale every morning).',"related":R(("en køkkenvægt","a kitchen scale"),("at veje","to weigh"),("en personvægt","a bathroom scale"))}
N["en bagagebærer"]={"explanation":'"En bagagebærer" means "a luggage rack / bike rack". It is built from "en bagage" (luggage) and "at bære" (to carry). To say you fasten a bag to the back of a bike, use "at spænde fast" (to strap on): "Jeg spænder tasken fast på bagagebæreren" (I strap the bag onto the rack).',"related":R(("en tagboks","a roof box"),("en kuffert","a suitcase"),("en cykelkurv","a bike basket"))}
N["en bageplade"]={"explanation":'"En bageplade" means "a baking tray". It is built from "at bage" (to bake) and "en plade" (a sheet). To say you cover it so nothing sticks, use "bagepapir" (baking paper): "Læg bagepapir på bagepladen" (Put baking paper on the baking tray).',"related":R(("en bageform","a baking pan"),("en ovnrist","an oven rack"),("en tærteform","a pie dish"))}
N["en bager"]={"explanation":'"En bager" means "a baker". It comes from "at bage" (to bake). To say you go to the bakery, Danish names the person instead of the shop: "Jeg går til bageren" (I am going to the bakery), literally "I am going to the baker".',"related":R(("et bageri","a bakery"),("en slagter","a butcher"),("en konditor","a pastry chef"))}
N["en baggrund"]={"explanation":'"En baggrund" means "a background". To say what is behind the main part of a picture or a scene, use "i baggrunden" (in the background): "Man kan se bjerge i baggrunden" (You can see mountains in the background). To talk about a person\'s past, such as their education and life so far, it also means "background": "Hun har en anden baggrund" (She has a different background).',"related":R(("en forgrund","a foreground"),("en erfaring","an experience"),("en uddannelse","an education"))}
N["en baggård"]={"explanation":'"En baggård" means "a backyard". It is built from "bag" (behind) and "en gård" (a yard). To talk about a farm, the same word "gård" is used: "Han bor på en gård" (He lives on a farm).',"related":R(("en have","a garden"),("en gårdsplads","a yard"),("en baghave","a back garden"))}
N["en baglygte"]={"explanation":'"En baglygte" means "a taillight". It is built from "bag" (back) and "en lygte" (a light). To tell someone to switch it on, use "at tænde" (to switch on): "Husk at tænde baglygten på cyklen" (Remember to switch on the taillight on the bike).',"related":R(("en forlygte","a headlight"),("et bremselys","a brake light"),("et blinklys","a turn signal"),("en cykellygte","a bike light"))}
N["en bagning"]={"explanation":'"En bagning" means "a baking". It comes from "at bage" (to bake). The ending "-ning" turns a verb into a noun in many words, such as "en tegning" (a drawing) from "at tegne" (to draw).',"related":R(("et bageri","a bakery"),("en bager","a baker"),("et bagværk","a pastry"),("en opskrift","a recipe"))}
N["en bagside"]={"explanation":'"En bagside" means "a back / downside". When you point to the rear of a page, a card or an envelope, it means "back": "Bagsiden af kuverten er tom" (The back of the envelope is empty). When you talk about the unwelcome part of something good, it means "downside": "Det er medaljens bagside" (That is the flip side of the medal).',"related":R(("en forside","a front"),("en underside","an underside"),("en ulempe","a drawback"),("en fordel","an advantage"))}
N["en baguette"]={"explanation":'"En baguette" means "a baguette". To say what is in it, use "med" (with): "en baguette med ost" (a baguette with cheese).',"related":R(("et franskbrød","a white loaf"),("en croissant","a croissant"),("et rundstykke","a bread roll"))}
N["en bakke"]={"explanation":'"En bakke" means "a hill". When you carry cups or plates on a flat board with a rim, it also means "a tray": "Jeg bærer en bakke med kaffe" (I carry a tray with coffee).',"related":R(("et bjerg","a mountain"),("en høj","a mound"),("en dal","a valley"),("en skråning","a slope"))}
N["en bakterie"]={"explanation":'"En bakterie" means "a bacterium". Spell it with a "k", not a "c" as in English. To say soap kills germs, use "at dræbe" (to kill): "Sæbe dræber bakterier" (Soap kills bacteria).',"related":R(("en mikrobe","a microbe"),("en infektion","an infection"),("en svamp","a fungus"),("et antibiotikum","an antibiotic"))}
N["en balje"]={"explanation":'"En balje" means "a tub". To talk about the tub you wash dishes in, add "opvaske" (washing-up): "Jeg skyller glassene i opvaskebaljen" (I rinse the glasses in the washing-up bowl).',"related":R(("en spand","a bucket"),("en skål","a bowl"),("et kar","a vat"))}
N["en balkon"]={"explanation":'"En balkon" means "a balcony". To say where you are sitting, use "på" (on): "Jeg sidder på balkonen" (I am sitting on the balcony).',"related":R(("en altan","a balcony"),("en terrasse","a patio"),("en lejlighed","an apartment"))}
N["en ballet"]={"explanation":'"En ballet" means "a ballet". To say someone does ballet as a dancer, use "at danse ballet" (to dance ballet) without "en": "Hun danser ballet" (She dances ballet).',"related":R(("en ballerina","a ballerina"),("en koreograf","a choreographer"),("en opera","an opera"))}
N["en ballon"]={"explanation":'"En ballon" means "a balloon". To say you fill a balloon with air, use "at puste op" (to blow up): "Jeg puster ballonen op" (I blow up the balloon).',"related":R(("en luftballon","a balloon"),("en varmluftsballon","a hot-air balloon"),("en bold","a ball"))}
N["en bamse"]={"explanation":'"En bamse" means "a teddy bear". When you describe a big, gentle, cuddly person, it also means "a teddy bear": "Han er en rigtig bamse" (He is a real teddy bear).',"related":R(("en dukke","a doll"),("et stykke legetøj","a toy"),("en bjørn","a bear"))}
N["en banan"]={"explanation":'"En banan" means "a banana". To say you take the skin off, use "at skrælle" (to peel): "Jeg skræller en banan" (I peel a banana).',"related":R(("en bananskræl","a banana peel"),("en frugt","a fruit"),("et æble","an apple"))}
N["en bandage"]={"explanation":'"En bandage" means "a bandage". For a small sticky one on a cut, use "et plaster" (an adhesive bandage): "Jeg sætter et plaster på fingeren" (I put an adhesive bandage on my finger).',"related":R(("en forbinding","a dressing"),("en slynge","a sling"),("en skinne","a splint"))}
save(0,N)
